#!/usr/bin/env bash
# aaxis-oro:managed-lint-php
# Generated by the aaxis-oro plugin (aaxis-oro setup sync): PHPCS and PHPMD exactly as CI and the local pre-commit hook run them.
# Do not edit; local edits are overwritten. Excludes: .stylelintignore (repo root), the one exclusion list for every linter.
# PHPCS standard: "lint"."phpcs-standard" in .oro-ai/config.json. Caches: $HOME/.phpcs-cache and $HOME/.phpmd-cache when CI is set, else the git dir.
# Usage: lint-php.sh [phpcs|phpmd]   (no argument runs both)    lint-php.sh --print-ignores
set -o pipefail

SRC_DIR='@@SRC@@'
PHPMD_RULESET='@@PHPMD_RULESET@@'

cd "$(git rev-parse --show-toplevel 2>/dev/null || pwd)" || exit 1

@@IGNORE_LIB@@

# CPU count: nproc, else getconf, else 1 (macOS without coreutils, minimal images).
cpu_jobs() {
    local n
    n="$(nproc 2>/dev/null || getconf _NPROCESSORS_ONLN 2>/dev/null)"
    [[ "$n" =~ ^[0-9]+$ && "$n" -ge 1 ]] && echo "$n" || echo 1
}

# cache_file <CI path under $HOME> <local file name in the git dir>
cache_file() {
    local gitdir
    if [[ -z "${CI:-}" ]] && gitdir="$(git rev-parse --absolute-git-dir 2>/dev/null)"; then
        printf '%s/%s' "$gitdir" "$2"
    else
        mkdir -p "$HOME/$(dirname "$1")"
        printf '%s/%s' "$HOME" "$1"
    fi
}

phpcs_standard() {
    local std
    std="$(php -r '$c = json_decode((string) @file_get_contents(".oro-ai/config.json"), true); echo is_array($c) ? ($c["lint"]["phpcs-standard"] ?? "") : "";' 2>/dev/null)"
    if [[ ! "$std" =~ ^[A-Za-z0-9_./,-]+$ ]]; then
        echo 'lint-php: set "lint": {"phpcs-standard": "<standard>"} in .oro-ai/config.json (aaxis-oro setup sync fills it)' >&2
        return 1
    fi
    printf '%s' "$std"
}

run_phpcs() {
    local std ignore
    std="$(phpcs_standard)" || return 1
    ignore="$(php_ignore_patterns phpcs)" || return 1
    echo "==> phpcs (standard ${std})"
    php ./vendor/squizlabs/php_codesniffer/bin/phpcs "$SRC_DIR" -p --encoding=utf-8 --extensions=php --standard="$std" \
        ${ignore:+--ignore="$ignore"} -q --parallel="$(cpu_jobs)" --cache="$(cache_file .phpcs-cache/phpcs.cache phpcs.cache)"
}

# pdepend (vendor) trips PHP 8.5 null-array-offset deprecations; hide only E_DEPRECATED, rule violations still fail.
run_phpmd() {
    local exclude
    exclude="$(php_ignore_patterns phpmd)" || return 1
    echo "==> phpmd"
    php -d error_reporting="E_ALL & ~E_DEPRECATED" ./vendor/phpmd/phpmd/src/bin/phpmd "$SRC_DIR" ansi "$PHPMD_RULESET" --suffixes php \
        ${exclude:+--exclude "$exclude"} --cache --cache-strategy content --cache-file "$(cache_file .phpmd-cache/result-cache.php phpmd.result-cache.php)"
}

case "${1:-all}" in
    --print-ignores) read_ignores ;;
    phpcs) run_phpcs ;;
    phpmd) run_phpmd ;;
    all)
        rc=0
        run_phpcs || rc=1
        run_phpmd || rc=1
        exit "$rc"
        ;;
    *)
        echo "usage: lint-php.sh [phpcs|phpmd|--print-ignores]" >&2
        exit 64
        ;;
esac
